package org.apache.commons.math.complex;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import org.apache.commons.math.util.MathUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class Complex_equals_TriageGen0Test {

    @Test
    public void testEquals_SameInstance() {
        Complex c1 = new Complex(1.0, 2.0);
        assertTrue("Should return true for the same instance", c1.equals(c1));
    }

    @Test
    public void testEquals_Null() {
        Complex c1 = new Complex(1.0, 2.0);
        assertFalse("Should return false when comparing with null", c1.equals(null));
    }

    @Test
    public void testEquals_DifferentClass() {
        Complex c1 = new Complex(1.0, 2.0);
        String other = "not a complex number";
        assertFalse("Should return false when comparing with a different class type", c1.equals(other));
    }

    @Test
    public void testEquals_EqualValues() {
        Complex c1 = new Complex(1.5, -2.5);
        Complex c2 = new Complex(1.5, -2.5);
        assertTrue("Should return true for complex numbers with same real and imaginary parts", c1.equals(c2));
    }

    @Test
    public void testEquals_DifferentReal() {
        Complex c1 = new Complex(1.0, 2.0);
        Complex c2 = new Complex(1.1, 2.0);
        assertFalse("Should return false when real parts differ", c1.equals(c2));
    }

    @Test
    public void testEquals_DifferentImaginary() {
        Complex c1 = new Complex(1.0, 2.0);
        Complex c2 = new Complex(1.0, 2.1);
        assertFalse("Should return false when imaginary parts differ", c1.equals(c2));
    }

    @Test
    public void testEquals_NaN_BothNaN() {
        // Using Double.NaN to trigger isNaN() logic
        Complex c1 = new Complex(Double.NaN, Double.NaN);
        Complex c2 = new Complex(Double.NaN, Double.NaN);
        assertTrue("Should return true if both are NaN", c1.equals(c2));
    }

    @Test
    public void testEquals_NaN_OneNaN() {
        Complex c1 = new Complex(Double.NaN, 1.0);
        Complex c2 = new Complex(1.0, 1.0);
        assertFalse("Should return false if only one is NaN", c1.equals(c2));
    }

    @Test
    public void testEquals_NaN_DifferentNaNStatus() {
        // c1 is NaN (real), c2 is not NaN
        Complex c1 = new Complex(Double.NaN, 1.0);
        Complex c2 = new Complex(1.0, 1.0);
        assertFalse("Should return false if rhs is NaN but this is not", c2.equals(c1));
    }

    @Test
    public void testEquals_EdgeCases_Zero() {
        // Testing positive and negative zero via bit representation
        // Double.doubleToRawLongBits(0.0) != Double.doubleToRawLongBits(-0.0)
        Complex c1 = new Complex(0.0, 0.0);
        Complex c2 = new Complex(-0.0, -0.0);

        // Based on the implementation using doubleToRawLongBits, 0.0 and -0.0 are NOT equal
        assertFalse("Should return false for 0.0 vs -0.0 due to raw long bits comparison", c1.equals(c2));
    }
}
